-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- disopyramide (CIS 66198796)
  m := pg_temp.jp_matrice_by_norm('disopyramide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTIARYTHMIQUE - Classe Ia, code ATC : C01BA03: système cardiovasculaire.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Le disopyramide NE DOIT JAMAIS ETRE UTILISE dans les cas suivants :', 'hypersensibilité au disopyramide ;', 'infarctus du myocarde (aigu ou ancien) sauf en cas de tachycardie ventriculaire menaçant le pronostic vital ;', 'insuffisance cardiaque, quel que soit le trouble rythmique ;', 'bloc de branche gauche complet, bloc bifasciculaire, bloc auriculoventriculaire du 2e et du 3e degré, dysfonctionnement sinusal et maladie de l''oreillette, en l''absence d''appareillage ;', 'allongement de QT préexistant ;', 'glaucome, myasthénie, troubles uréthroprostatiques, notamment hypertrophie prostatique (liés à l''activité anticholinergique du disopyramide).', 'association avec les médicaments donnant des torsades de pointes :', 'o les antiarythmiques de classe Ia (hydroquinidine, quinidine),', 'o les antiarythmiques de classe III (amiodarone, sotalol, dofétilide, ibutilide),', 'o le sultopride (neuroleptique),', 'o et autres médicaments tels que: bépridil, cisapride, diphémanil, érythromycine IV, mizolastine, vincamine IV...']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'Comme pour les autres antiarythmiques de classe I, il n''existe pas d''essai contrôlé mettant en évidence un effet bénéfique du disopyramide en termes de survie ou de mort subite.', 'En raison de la présence de saccharose, ce médicament est contre-indiqué en cas d''intolérance au fructose, de syndrome de malabsorption du glucose et du galactose ou de déficit en sucrase-isomaltase.', 'Précautions d''emploi', 'Effets pro-arythmiques', 'Le disopyramide, comme d''autres agents anti-arythmiques, peut provoquer la survenue d''une forme plus sévère d''arythmie, augmenter la fréquence d''une arythmie préexistante ou aggraver la sévérité des symptômes.', 'Une variation spontanée du trouble du rythme propre au patient peut se révéler difficile à distinguer d''une aggravation secondaire à l''administration du médicament.', 'L''apparition d''extrasystoles ventriculaires plus nombreuses ou polymorphes doit faire interrompre le traitement.', 'Antécédents d''insuffisance cardiaque', 'Modifications électrocardiographiques', 'Le disopyramide doit être administré avec précaution chez les patients ayant des anomalies préexistantes de conduction.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Risque majoré de troubles ventriculaires, notamment de torsades de pointes.', '+ Bêta-bloquants dans l''insuffisance cardiaque (bisoprolol, carvédilol, métoprolol)', 'Effet inotrope négatif avec risque de décompensation cardiaque (synergie des effets).', 'Associations déconseillées', '+ Erythromycine (voie orale), clarithromycine, josamycine', 'Risque de majoration des effets indésirables du disopyramide: hypoglycémies sévères, allongement de l''intervalle QT et troubles du rythme ventriculaire graves, notamment à type de torsade de pointes.', '+ Certains neuroleptiques (thioridazine, chlorpromazine, lévomépromazine, trifluopérazine, cyamémazine, sulpiride, amisulpride, tiapride, halopéridol, pimozide, dropéridol...)', 'Risque majoré de troubles du rythme ventriculaire, notamment de torsades de pointes.', '+ Halofantrine, pentamidine, moxifloxacine', 'Si cela est possible, interrompre le médicament torsadogène non anti-infectieux.', 'Si l''association ne peut être évitée, contrôle préalable du QT et surveillance électrocardiographique monitorée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Comme tous les antiarythmiques, le disopyramide peut entraîner l''aggravation ou l''apparition de troubles du rythme ventriculaire (tachycardie ventriculaire, fibrillation ventriculaire, torsades de poi', 'Le disopyramide augmente l''intervalle QT et peut être responsable de torsades de pointes.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.']);

  -- flecainide (CIS 69087107)
  m := pg_temp.jp_matrice_by_norm('flecainide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : anti-arythmique classe IC, code ATC : C01BC04');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT PAS ETRE UTILISE dans les cas suivants :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'infarctus du myocarde (aigu ou ancien) sauf en cas de tachycardie ventriculaire menaçant le pronostic vital,', 'insuffisance cardiaque, quel que soit le trouble rythmique,', 'bloc de branche gauche complet, bloc bifasciculaire, bloc auriculo-ventriculaire du 2ème et du 3ème degré, dysfonctionnement sinusal et maladie de l''oreillette, en l''absence d''appareillage,', 'choc cardiogénique,', 'syndrome de Brugada connu.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''incidence de la mortalité et des arrêts cardiaques non mortels sous flécaïnide a été supérieure à celle observée dans le groupe sous contrôle placebo.', 'Comme pour les autres antiarythmiques de classe I, il n''existe pas d''essai contrôlé mettant en évidence un effet bénéfique de l''acétate de flécaïnide en termes de survie ou de mort subite.', 'Le traitement par flécaïnide doit être initié par un médecin ayant la compétence de la prise en charge des patients atteints de cardiopathies.', 'Toute instauration ou changement dans la prescription nécessite en effet une surveillance clinique et électrocardiographique permettant d’évaluer l’effet du traitement.', 'Lors du changement d’un médicament contenant du flécaïnide à un autre, il est recommandé pour les patients à risque d’effectuer une surveillance étroite.', 'Précautions particulières d''emploi', 'Effets pro-arythmiques', 'Une variation spontanée du trouble du rythme propre au patient peut se révéler difficile à distinguer d''une aggravation secondaire à l''administration du médicament.', 'L''apparition d''extrasystoles ventriculaires plus nombreuses ou polymorphes doit faire interrompre le traitement.', 'Antécédents d''insuffisance cardiaque', 'Modifications électrocardiographiques']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle ECG.', 'L’association d’antiarythmiques de même classe est déconseillée sauf cas exceptionnels en raison du risque accru d’effets indésirables cardiaques.', 'Associations déconseillées', '+ Anti-arythmiques de classe I (quinidine, hydroquinidine, disopyramide, mexilétine, lidocaïne, propafénone, cibenzoline)', 'L''acétate de flécaïnide ne doit pas être associé avec les autres anti-arythmiques de la classe I, sauf cas exceptionnels, en raison du risque accru d''effets cardiaques indésirables.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['très fréquent (≥ 1/10),', 'fréquent (≥ 1/100,', 'peu fréquent (≥ 1/1 000,', 'rare (≥ 1/10 000 à', 'très rare (≤ 1/10 000),', 'Peu fréquent : diminution du nombre de globules rouges, diminution du nombre de globules blancs et diminution du nombre de plaquettes.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''incidence de la mortalité et des arrêts cardiaques non mortels sous flécaïnide a été supérieure à celle observée dans le groupe sous contrôle placebo.', 'Toute instauration ou changement dans la prescription nécessite en effet une surveillance clinique et électrocardiographique permettant d’évaluer l’effet du traitement.', 'Lors du changement d’un médicament contenant du flécaïnide à un autre, il est recommandé pour les patients à risque d’effectuer une surveillance étroite.']);

  -- propafenone (CIS 67377300)
  m := pg_temp.jp_matrice_by_norm('propafenone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antiarythmiques de la classe Ic, code ATC : C01BC03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Tachyarythmies ventriculaires symptomatiques sévères, si le médecin juge qu’elles menacent le pronostic vital.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au chlorhydrate de propafénone ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Syndrome de Brugada connu (voir rubrique 4.4).', 'Cardiopathie structurale importante, telle que :', 'o Infarctus du myocarde au cours des 3 derniers mois.', 'o Insuffisance cardiaque congestive non contrôlée avec débit ventriculaire gauche inférieur à 35 %.', 'o Choc cardiogénique, sauf si celui-ci est provoqué par l’arythmie.', 'o Bradycardie symptomatique sévère.', 'o Hypotension sévère.', 'Trouble manifeste de l’équilibre électrolytique (par ex., troubles du métabolisme du potassium).', 'Bronchopneumopathie obstructive sévère.', 'Myasthénie grave.', 'Traitement concomitant par le ritonavir.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['La propafénone comme les autres antiarythmiques peut provoquer des effets proarythmiques i.e. elle peut provoquer de nouvelles arythmies ou aggraver des arythmies préexistantes (voir rubrique 4.8).', 'L’exposition à la propafénone chez les porteurs asymptomatiques du syndrome de Brugada peut révéler le syndrome ou entraîner des modifications sur l’ECG semblables à celles induites par un syndrome de Brugada.', 'Après l’initiation du traitement par la propafénone, tout symptôme suggérant un syndrome de Brugada doit imposer la réalisation d’un ECG (voir rubrique 4.3).', 'Il convient de contrôler les signes d’une insuffisance cardiaque avant d’administrer la propafénone chez les patients qui présentent une insuffisance cardiaque décompensée.', 'Le faible effet inotrope négatif de la propafénone peut être important chez les patients prédisposés à l’insuffisance cardiaque.', 'Comme avec d’autres antiarythmiques de classe Ic, les patients atteints d’une cardiopathie structurale importante peuvent être prédisposés à développer des effets indésirables graves.', 'Le chlorhydrate de propafénone est donc contre-indiqué chez ces patients (voir rubrique 4.3)', 'Ce médicament contient du sodium', 'Ce médicament contient moins de 1 mmol (23 mg) de sodium par comprimé, c’est-à-dire qu’il est essentiellement « sans sodium ».']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Il n''a pas été noté d''effet significatif sur la pharmacocinétique de la propafénone et de la lidocaïne lors de leur administration concomitante.', 'Cependant, il a été rapporté que l''association de propafénone et de lidocaïne augmente le risque d''effets indésirables neurologiques centraux de la lidocaïne.', 'Des augmentations des concentrations plasmatiques de propranolol, métoprolol, désipramine, ciclosporine, théophylline et digoxine ont été rapportées au cours de traitements par la propafénone.', 'Les doses de ces médicaments doivent être réduites comme approprié si des signes de surdosage sont observés.', 'Une posologie plus faible de propafénone peut être suffisante pour obtenir l''effet thérapeutique souhaité.', 'Les posologies de ces médicaments doivent être adaptées si nécessaire.', 'La co-administration de propafénone avec des médicaments métabolisés par le CYP2D6 (comme la venlafaxine) peut augmenter leurs concentrations plasmatiques.', 'Une surveillance clinique étroite et une adaptation de la posologie sont nécessaires lors de l’administration concommitante de propafénone avec des inhibiteurs de ces enzymes.', 'Un traitement combiné associant amiodarone et chlorhydrate de propafénone peut affecter la conduction et la repolarisation et mener à des anomalies susceptibles d’être pro-arythmiques.', 'Un ajustement des doses des deux composants peut être nécessaire.', 'L’administration concomitante de propafénone et de médicaments inducteurs du CYP3A4 (phénobarbital, rifampicine) peut diminuer les concentrations plasmatiques de propafénone et donc son efficacité antiarythmique.', 'La réponse à un traitement par la propafénone doit être surveillée lors de traitement concomitant chronique par le phénobarbital et/ou la rifampicine.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents et très fréquents, associés au traitement par la propafénone sont des étourdissements, des troubles de la conduction cardiaque et des palpitations.', 'Très fréquent ≥1/10', 'Fréquent ≥ 1/100 à', 'Peu fréquent≥ 1/1000 à', 'Agranulocytose']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Il convient de contrôler les signes d’une insuffisance cardiaque avant d’administrer la propafénone chez les patients qui présentent une insuffisance cardiaque décompensée.']);

  -- amiodarone (CIS 69364999)
  m := pg_temp.jp_matrice_by_norm('amiodarone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antiarythmiques classe III, code ATC : C01BD01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention des récidives des :', 'tachycardies ventriculaires menaçant le pronostic vital : le traitement doit être instauré en milieu hospitalier sous monitorage ;', 'tachycardies ventriculaires documentées symptomatiques et invalidantes ;', 'tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie en cas de résistance ou de contre-indication aux autres thérapeutiques ;', 'fibrillations ventriculaires.', 'Traitement des tachycardies supraventriculaires :', 'Ralentissement ou réduction de la fibrillation auriculaire ou du flutter auriculaire.', 'L''amiodarone peut être utilisée en présence d''une maladie coronarienne et/ou d''une altération de la fonction ventriculaire gauche (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué dans les situations suivantes :', 'bradycardie sinusale et blocs sino-auriculaires non appareillés ;', 'maladie du sinus non appareillée (risque d''arrêt sinusal) ;', 'troubles conductifs auriculo-ventriculaires de haut degré non appareillés ;', 'hyperthyroïdie en raison de sa possible aggravation par l''amiodarone ;', 'hypersensibilité à l’amiodarone ou à l’iode ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'les 2ème et 3ème trimestres de la grossesse ;', 'allaitement ;', 'en association avec :', 'o les médicaments torsadogènes (sauf antiparasitaires, neuroleptiques et méthadone) :', '§ les antiarythmiques de classe Ia (quinidine, hydroquinidine, disopyramide) ;', '§ les antiarythmiques de classe III (sotalol, dofétilide, ibutilide) ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Effets cardiaques', 'Un ECG doit être pratiqué avant l''initiation du traitement.', 'Le ralentissement de la fréquence cardiaque peut être plus accentué chez les malades âgés.', 'Sous amiodarone, l''électrocardiogramme est modifié.', 'La survenue sous traitement d''un bloc auriculo-ventriculaire du 2ème ou 3ème degré, d''un bloc sino‑auriculaire ou d''un bloc bifasciculaire doit faire arrêter le traitement.', 'Un bloc auriculo‑ventriculaire du 1er degré doit faire renforcer la surveillance.', 'La survenue d''un nouveau trouble du rythme ou l''aggravation d''un trouble du rythme préexistant et traité, a été rapportée (voir rubrique 4.8).', 'Le risque d’induire des torsades de pointes sous amiodarone apparaît moindre à degré égal d’allongement de l’intervalle qu’avec d’autres antiarythmiques.', 'Manifestations thyroïdiennes', 'La présence d''iode dans la molécule fausse certains tests thyroïdiens (fixation de l''iode radioactif, PBI) ; néanmoins, un bilan thyroïdien est toujours possible (T3, T4, TSH-us).', 'L''amiodarone peut entraîner des anomalies thyroïdiennes, particulièrement chez les patients ayant des antécédents de troubles thyroïdiens.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments antiarythmiques', 'De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l’ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d’effets indésirables cardiaques.', 'Médicaments susceptibles de donner des torsades de pointes', 'Ce trouble du rythme cardiaque grave peut être provoqué par un certain nombre de médicaments, antiarythmiques ou non.', 'L''hypokaliémie (cf. médicaments hypokaliémiants) est un facteur favorisant, de même que la bradycardie (cf. médicaments bradycardisants) ou un allongement préexistant de l''intervalle QT, congénital ou acquis.', 'Les médicaments concernés sont notamment des antiarythmiques de classe Ia et III, certains neuroleptiques.', 'Pour le dolasétron, l’érythromycine, la spiramycine et la vincamine, seules les formes administrées par voie intraveineuse sont concernées par cette interaction.', 'L''utilisation d''un médicament torsadogène avec un autre médicament torsadogène est contre-indiquée en règle générale.', 'Toutefois, certains d’entre eux, en raison de leur caractère incontournable, font exception à la règle, en étant seulement déconseillés avec les torsadogènes.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables ont été classés par système-organe et par fréquence, selon les conventions suivantes :', 'Affections oculaires', 'Très fréquemment :', 'micro-dépôts cornéens, quasiment constants chez l''adulte, restant habituellement localisés à l''aire sous-pupillaire et ne contre-indiquant pas la poursuite du traitement.', 'Exceptionnellement, ils peuvent s''accompagner de perception de halos colorés en lumière éblouissante, ou de sensation de brouillard.', 'Constitués de dépôts lipidiques complexes, les micro-dépôts cornéens sont toujours entièrement réversibles à l''arrêt du traitement.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Un bloc auriculo‑ventriculaire du 1er degré doit faire renforcer la surveillance.', 'La présence d''iode dans la molécule fausse certains tests thyroïdiens (fixation de l''iode radioactif, PBI) ; néanmoins, un bilan thyroïdien est toujours possible (T3, T4, TSH-us).']);

  -- fosinopril (CIS 67633778)
  m := pg_temp.jp_matrice_by_norm('fosinopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l''enzyme de conversion (IEC) non associés, code ATC : C09AA09.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle,', 'Insuffisance cardiaque congestive.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé en cas de :', 'hypersensibilité à la substance active ou à l’un des excipients, mentionnés à la rubrique 6.1 ;', 'antécédent d''angiœdème (œdème de Quincke) lié à la prise d''un inhibiteur de l''enzyme de conversion ;', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6) ;', 'utilisation concomitante avec un traitement par sacubitril/valsartan.', 'Le traitement par fosinopril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).', 'Ce médicament ne doit généralement pas être utilisé dans les cas suivants :', 'associations avec les diurétiques hyperkaliémiants, les sels de potassium, l''estramustine et le lithium (voir rubrique 4.5) ;', 'sténose bilatérale de l''artère rénale ou sur rein fonctionnellement unique ;', 'hyperkaliémie ;', 'grossesse (1er trimestre).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Risque de neutropénie/ Agranulocytose sur terrain immunodéprimé', 'Des inhibiteurs de l''enzyme de conversion ont exceptionnellement entraîné une agranulocytose et/ou une dépression médullaire lorsqu''ils étaient administrés :', 'à doses élevées,', 'chez des patients insuffisants rénaux associant des maladies de système (collagénoses telles que lupus érythémateux disséminé ou sclérodermie), avec un traitement immunosuppresseur et/ou potentiellement leucopéniant.', 'Le strict respect des posologies préconisées semble constituer la meilleure prévention de la survenue de ces événements.', 'Toutefois, si un inhibiteur de l''enzyme de conversion doit être administré chez ce type de patients, le rapport bénéfice/risque sera soigneusement mesuré.', 'Hypersensibilité/angio-œdème', 'Un angio-œdème de la face, des extrémités, des lèvres, de la langue, de la glotte et/ou du larynx a été rarement signalé chez les patients traités par un inhibiteur de l''enzyme de conversion, fosinopril inclus.', 'Dans de tels cas, le fosinopril doit être arrêté immédiatement et le patient surveillé jusqu''à disparition de l''œdème.', 'Lorsque l''œdème ne concerne que la face et les lèvres, l''évolution est en général régressive sans traitement, bien que les antihistaminiques aient été utilisés pour soulager les symptômes.', 'L''angio-œdème associé à un œdème laryngé peut être fatal.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments hyperkaliémiants', 'L''association de ces médicaments majore le risque d''hyperkaliémie.', 'Pour connaître les risques et les niveaux de contrainte spécifiques aux médicaments hyperkaliémiants, il convient de se reporter aux interactions propres à chaque substance.', 'Toutefois, certaines substances, comme le triméthoprime, ne font pas l''objet d''interactions spécifiques au regard de ce risque.', 'Néanmoins, ils peuvent agir comme facteurs favorisants lorsqu''ils sont associés à d''autres médicaments déjà mentionnés dans ce chapitre.', 'Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec le racécadotril, les inhibiteurs de mTOR (par exemple sirolimus, évérolimus, temsirolimus) et la vildagliptine peut entraîner un risque accru d’angio-œdème (voir rubrique 4.4).', 'Associations contre-indiquées', '+ Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubriques 4.3 et 4.4).', 'Associations déconseillées', '+ Diurétiques épargneurs de potassium, suppléments potassiques ou substituts de sel contenant du potassium']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['exceptionnellement : angio-œdème (œdème de Quincke) (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dans de tels cas, le fosinopril doit être arrêté immédiatement et le patient surveillé jusqu''à disparition de l''œdème.']);

  -- losartan (CIS 64201553)
  m := pg_temp.jp_matrice_by_norm('losartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique: Antagonistes de l’angiotensine II, non associés, code ATC: C09CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle essentielle chez les adultes et les enfants et adolescents âgés de 6 à 18 ans.', 'Traitement de l''atteinte rénale chez les patients adultes diabétiques de type 2, hypertendus, avec protéinurie ≥ 0,5 g/jour, dans le cadre d''un traitement antihypertenseur (voir rubriques 4,3, 4,4, 4,5 et 5,1).', 'Le losartan ne doit pas être utilisé en traitement de relais chez les patients atteints d''insuffisance cardiaque, stabilisés par un IEC.', 'Les patients doivent avoir une fraction d''éjection ventriculaire gauche ≤ 40 % et doivent être cliniquement stabilisés et sous un traitement régulier pour l''insuffisance cardiaque chronique.', 'Réduction du risque d''accident vasculaire cérébral chez les patients adultes hypertendus présentant une hypertrophie ventriculaire gauche à l''électrocardiogramme (voir rubrique 5.1: Etude LIFE, particularités ethniques).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés aux rubriques 4.4 et 4.6.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'Insuffisance hépatique sévère.', 'L’administration concomitante du losartan avec les médicaments contenant de l''aliskiren est contre-indiquée chez les patients atteints de diabète ou d’insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypersensibilité', 'Angio-œdème.', 'Il convient de surveiller étroitement les patients ayant des antécédents d''angio-œdème (gonflement du visage, des lèvres, de la gorge et/ou de la langue) (voir rubrique 4.8).', 'Hypotension et déséquilibres hydro-électrolytiques', 'Il convient de traiter ces pathologies avant l''administration du losartan ou d''instaurer le traitement à une posologie plus faible (voir rubrique 4.2).', 'Ceci s''applique aussi aux enfants et aux adolescents de 6 à 18 ans.', 'Déséquilibres électrolytiques', 'Les déséquilibres électrolytiques sont fréquents et doivent être pris en compte chez les patients présentant une insuffisance rénale, qu''ils soient diabétiques ou non.', 'Insuffisance hépatique', 'Il n''y a pas d''expérience clinique avec le losartan chez les patients présentant une insuffisance hépatique sévère.', 'Le losartan ne doit donc pas être utilisé en cas d''insuffisance hépatique sévère (voir rubriques 4.2, 4.3 et 5.2).', 'Le losartan ne doit pas être utilisé chez les enfants présentant une insuffisance hépatique (voir rubrique 4.2).']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['D''autres antihypertenseurs peuvent majorer l''action hypotensive du losartan.', 'Le losartan est principalement métabolisé par le cytochrome P450 (CYP) 2C9 en son métabolite acide carboxylique actif.', 'Il a été observé dans une étude clinique que le fluconazole (un inhibiteur du CYP2C9) diminue l''exposition au métabolite actif d''environ 50 %.', 'La concentration plasmatique du métabolite actif est diminuée de 40 % en cas d''administration concomitante de losartan et de rifampicine (un inducteur des enzymes du métabolisme).', 'La pertinence clinique de cet effet est inconnue.', 'Aucune différence en termes d''exposition n''a été observée en cas d''administration concomitante avec la fluvastatine (un inhibiteur faible du CYP2C9).', 'Une administration concomitante est déconseillée.', 'Des augmentations réversibles de la lithémie avec phénomène toxique associé ont été rapportées lors de l''administration concomitante de lithium et d''IEC.', 'De très rares cas ont également été rapportés avec les antagonistes des récepteurs de l''angiotensine II.', 'La prudence s''impose en cas de co-administration de lithium et de losartan.', 'Si cette association s''avère indispensable, il est recommandé de surveiller la lithémie.', 'L''association doit être administrée avec prudence, en particulier chez le sujet âgé.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Dans ces études cliniques, les étourdissements ont été l''effet indésirable le plus fréquent.', 'La fréquence des effets indésirables répertoriés ci-dessous est définie selon la convention suivante: très fréquent (≥ 1/10); fréquent (≥ 1/100 ;']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Il convient de surveiller étroitement les patients ayant des antécédents d''angio-œdème (gonflement du visage, des lèvres, de la gorge et/ou de la langue) (voir rubrique 4.8).']);

  -- valsartan (CIS 69593873)
  m := pg_temp.jp_matrice_by_norm('valsartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antagonistes de l’angiotensine II, non associés, code ATC : C09CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension', 'Traitement de l’hypertension artérielle essentielle chez les adultes, et de l’hypertension chez les enfants et les adolescents âgés de 6 ans à moins de 18 ans.', 'Post-infarctus du myocarde récent', 'Insuffisance cardiaque']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance hépatique sévère, cirrhose biliaire et cholestase.', 'Deuxième et troisième trimestres de grossesse (voir rubriques 4.4 et 4.6).', 'Utilisation concomitante de VALSARTAN ARROW LAB avec des médicaments contenant de l’aliskiren chez les patients présentant un diabète ou une insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hyperkaliémie', 'Un contrôle du potassium doit être mis en œuvre le cas échéant.', 'Altération de la fonction rénale', 'Il n’y a actuellement pas d’expérience sur l’innocuité du valsartan chez les patients dont la clairance de la créatinine est 10 mL/min (voir rubriques 4.2 et 5.2).', 'Insuffisance hépatique', 'VALSARTAN ARROW LAB doit être utilisé avec prudence chez les patients atteints d’insuffisance hépatique légère à modérée sans cholestase (voir rubriques 4.2 et 5.2).', 'Déplétion sodée et/ou volumique', 'Un déficit sodé et/ou volumique doit être corrigé avant le début d’un traitement par VALSARTAN ARROW LAB, en réduisant par exemple la dose de diurétiques.', 'Sténose de l’artère rénale', 'L’innocuité du valsartan n’a pas été établie chez les patients présentant une sténose bilatérale des artères rénales ou une sténose de l’artère rénale sur rein unique.', 'Un suivi de la fonction rénale est donc recommandé chez les patients traités par valsartan.', 'Transplantation rénale']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Double blocage du système rénine-angiotensine-aldostérone (SRAA) avec les ARA II, les IEC, ou l’aliskiren', 'Associations déconseillées', 'Si cette association est nécessaire, une surveillance stricte de la lithémie est recommandée.', 'Si un diurétique est également utilisé, le risque de toxicité du lithium peut vraisemblablement être augmenté.', 'Diurétiques épargneurs de potassium, suppléments potassiques, substituts du sel contenant du potassium et autres substances pouvant augmenter les taux de potassium', 'Une surveillance des concentrations plasmatiques de potassium est recommandée en cas d''association jugée nécessaire de valsartan avec un médicament agissant sur les taux de potassium.', 'Associations faisant l''objet de précautions d’emploi', 'Anti-inflammatoires non stéroïdiens (AINS), y compris les inhibiteurs sélectifs de la COX-2, l''acide acétylsalicylique à plus de 3 g/jour et les AINS non sélectifs', 'Une atténuation de l''effet antihypertenseur peut survenir en cas d''administration concomitante d''antagonistes de l''angiotensine II et d''AINS.', 'De plus, cette association peut conduire à une augmentation du risque d''altération/aggravation de la fonction rénale et d''augmentation du potassium sérique.', 'Par conséquent, il convient de surveiller la fonction rénale en début de traitement et de maintenir un état d''hydratation approprié du patient.', 'Transporteurs']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Diminution de l’hémoglobine, diminution de l’hématocrite, neutropénie, thrombocytopénie']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Hyperkaliémie', 'Un contrôle du potassium doit être mis en œuvre le cas échéant.', 'Altération de la fonction rénale', 'Il n’y a actuellement pas d’expérience sur l’innocuité du valsartan chez les patients dont la clairance de la créatinine est 10 mL/min (voir rubriques 4.2 et 5.2).', 'Un suivi de la fonction rénale est donc recommandé chez les patients traités par valsartan.']);

  -- candesartan (CIS 61010703)
  m := pg_temp.jp_matrice_by_norm('candesartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antagonistes des récepteurs de l''angiotensine II, code ATC : C09CA06.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['CANDESARTAN ARROW est indiqué dans :', 'traitement de l''hypertension artérielle primaire chez l''adulte ;', 'traitement de l’hypertension chez l’enfant et l’adolescent âgés de 6 à 18 ans ;', 'Le traitement chez l’adulte de l’insuffisance cardiaque avec dysfonction systolique ventriculaire gauche (fraction d’éjection ventriculaire gauche ≤ 40 %) :', 'o en cas d’intolérance aux inhibiteurs de l’enzyme de conversion (IEC)']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au candésartan cilexetil ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'Insuffisance hépatique sévère et/ou cholestase.', 'Enfant âgé de moins d’un an (voir rubrique 5.3).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Double blocage du système rénine-angiotensine-aldostérone (SRAA)', 'En conséquence, le double blocage du SRAA par l’association d’IEC, d’ARA II ou d’aliskiren, n’est pas recommandé (voir rubriques 4.5 et 5.1).', 'Les IEC et les ARA II ne doivent pas être associés chez les patients atteints d’une néphropathie diabétique.', 'Insuffisance rénale', 'Quand CANDESARTAN ARROW est utilisé chez les patients hypertendus présentant une insuffisance rénale, une surveillance périodique des taux sériques de potassium et de créatinine est recommandée.', 'Lors de l''augmentation de la dose de CANDESARTAN ARROW, il est recommandé de surveiller les taux sériques de potassium et de créatinine.', 'Les essais cliniques réalisés dans l''insuffisance cardiaque n''incluaient aucun patient avec une créatinine sérique > 265 µmol/l (> 3 mg/dL).', 'Population pédiatrique, incluant les patients pédiatriques présentant une atteinte de la fonction rénale', 'Le candésartan n''a pas été étudié chez des enfants présentant un débit de filtration glomérulaire inférieur à 30 mL/min/1,73 m2 (voir rubrique 4.2).', 'Traitement associé à un inhibiteur de l''enzyme de conversion (IEC) dans l''insuffisance cardiaque', 'La triple association d''un IEC, d’un antagoniste de l’aldostérone et du candésartan n''est pas recommandée.', 'L’utilisation de ces associations doit être faite sous le contrôle d’un spécialiste et il faut surveiller régulièrement la fonction rénale, l’ionogramme sanguin et la pression artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune interaction pharmacocinétique cliniquement significative avec ces médicaments n''a été identifiée.', 'Une surveillance régulière de la kaliémie doit être effectuée le cas échéant (voir rubrique 4.4).', 'Des augmentations réversibles des concentrations sériques de lithium et de la toxicité ont été observées au cours de l''administration concomitante de lithium et d''inhibiteurs de l''enzyme de conversion (IEC).', 'Un effet similaire peut survenir avec les ARAII.', 'L''utilisation du candésartan et du lithium n''est pas recommandée.', 'Si l''association est indispensable, une surveillance attentive des taux sériques de lithium est recommandée.', 'L''association doit être utilisée avec prudence, en particulier chez les patients âgés.', 'Les patients doivent être hydratés correctement et une surveillance de la fonction rénale sera mise en place à l''initiation du traitement concomitant, puis périodiquement par la suite.', 'Population pédiatrique', 'Les études d''interactions n''ont été réalisées que chez l''adulte.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences utilisées dans les tableaux de la rubrique 4.8 sont les suivantes : très fréquent (≥ 1/10), fréquent (≥ 1/100 à', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Quand CANDESARTAN ARROW est utilisé chez les patients hypertendus présentant une insuffisance rénale, une surveillance périodique des taux sériques de potassium et de créatinine est recommandée.', 'Lors de l''augmentation de la dose de CANDESARTAN ARROW, il est recommandé de surveiller les taux sériques de potassium et de créatinine.', 'Les essais cliniques réalisés dans l''insuffisance cardiaque n''incluaient aucun patient avec une créatinine sérique > 265 µmol/l (> 3 mg/dL).', 'Population pédiatrique, incluant les patients pédiatriques présentant une atteinte de la fonction rénale', 'L’utilisation de ces associations doit être faite sous le contrôle d’un spécialiste et il faut surveiller régulièrement la fonction rénale, l’ionogramme sanguin et la pression artérielle.']);

  -- digoxine (CIS 67681303)
  m := pg_temp.jp_matrice_by_norm('digoxine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : GLUCOSIDE CARDIOTONIQUE code ATC : C01AA05 (Système cardiovasculaire).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Insuffisance cardiaque.', 'troubles du rythme supraventriculaire: ralentissement ou réduction de la fibrillation auriculaire ou du flutter auriculaire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Ce médicament ne doit jamais être utilisé en cas de:', 'blocs auriculo-ventriculaires du 2ème et du 3ème degré non appareillés,', 'hyperexcitabilité ventriculaire (notamment extrasystoles) survenant quand le malade est encore sous l''action d''un digitalique (voir rubrique 4.4),', 'tachycardies atriales (flutter, tachysystolie) et fibrillation auriculaire associée à un syndrome de Wolff-Parkinson-White,', 'tachycardie et fibrillation ventriculaires,', 'hypokaliémie non corrigée,', 'association au sultopride, au calcium (sels de) voie IV, au millepertuis (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''arrêt des digitaliques est impératif en cas d''hyperexcitabilité ventriculaire (notamment extrasystoles) liée à une hypersensibilité, à un surdosage ou à une hypokaliémie.', 'Il est conseillé d''arrêter le traitement 3 jours (2 demi-vies) avant un choc électrique.', 'Ce médicament est généralement déconseillé en association à la midodrine (voir rubrique 4.5).', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Précautions d''emploi', 'Ce médicament doit être utilisé avec prudence en cas de cardiomyopathie hypertrophique et cardiomyopathie restrictive.', 'Une surveillance attentive du traitement, avec contrôle ECG, est recommandée, en particulier en cas de:', 'insuffisance rénale sévère; il est alors nécessaire d''ajuster la posologie en fonction de la clairance de la créatinine,', 'insuffisance hépatique sévère.', 'Une surveillance clinique et électrocardiographique attentive est également recommandée en début de traitement:', 'dans les insuffisances cardiaques avec B.A.V. du 1° degré,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments bradycardisants', 'De nombreux médicaments peuvent entraîner une bradycardie.', 'C''est le cas notamment des antiarythmiques de classe Ia, des bêta-bloquants, de certains antiarythmiques de classe III, de certains antagonistes du calcium, des anticholinestérasiques, de la pilocarpine etc.', 'Associations contre-indiquées', '(voir rubrique 4.3)', '+ Calcium (sels de) (voie I.V.)', 'Risque de troubles du rythme graves, voire mortels.', '+ Millepertuis', 'En cas d''association fortuite, ne pas interrompre brutalement la prise de millepertuis mais contrôler les concentrations plasmatiques (ou l''efficacité) de la digoxine avant puis après l''arrêt du millepertuis.', '+ Sultopride', 'Risque majoré de trouble du rythme ventriculaire, notamment de torsades de pointes.', 'Associations déconseillées']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les troubles digestifs (nausées, vomissements, diarrhées), sont les premiers symptômes fréquents et précoces de la toxicité digitalique.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''arrêt des digitaliques est impératif en cas d''hyperexcitabilité ventriculaire (notamment extrasystoles) liée à une hypersensibilité, à un surdosage ou à une hypokaliémie.', 'Une surveillance attentive du traitement, avec contrôle ECG, est recommandée, en particulier en cas de:', 'insuffisance rénale sévère; il est alors nécessaire d''ajuster la posologie en fonction de la clairance de la créatinine,', 'Une surveillance clinique et électrocardiographique attentive est également recommandée en début de traitement:']);

END
$mig$;
